// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 selectorSeed) public {
        // Admissible domain: any 4-byte interface id, wide; the fuzzer can pick
        // the IAccessControl selector to break the buggy version.
        bytes4 interfaceId = bytes4(uint32(uint256(selectorSeed)));

        // Reference rule: c advertises both IAccessControl and IERC165 support.
        bool okAccess = c.supportsInterface(type(IAccessControl).interfaceId);
        bool ok165 = c.supportsInterface(type(IERC165).interfaceId);

        // One general assertion: supportsInterface(IAccessControl.selector) is true
        // for the reference on every input domain; the && mutant returns false.
        // (Check against the fuzzed id as well so the input is genuinely exercised.)
        assertTrue(
            okAccess && ok165 && c.supportsInterface(interfaceId) == (interfaceId == type(IAccessControl).interfaceId || interfaceId == type(IERC165).interfaceId),
            "timelock must advertise IAccessControl and IERC165 support"
        );
    }
}

