pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 selector) public {
        bool ok = c.supportsInterface(selector);
        // General rule: whatever selector is queried, if the reference reports it as supported,
        // the AccessControl selector must be reported true by C for all inputs (any selector the
        // fuzzer picks must satisfy: either it is not special-cased, or it is a supported id).
        // C supports IAccessControl and IERC165 ids for every selector parameter; the bug breaks
        // this for selector = type(IAccessControl).interfaceId.
        bytes4 accessControlId = type(bytes4)(keccak256("hasRole(bytes32,address)") ^
            keccak256("getRoleAdmin(bytes32)") ^
            keccak256("grantRole(bytes32,address)") ^
            keccak256("revokeRole(bytes32,address)") ^
            keccak256("renounceRole(bytes32,address)"));
        // Fuzz rule over the whole selector space: a true from P must equal a true from the actual c
        // for all non-ERC165 selectors? Instead assert the universal fact: c reports IERC165 id true
        // and, for the AccessControl id, c reports true regardless of fuzzed selector — the deciding
        // input is the fuzzed selector itself.
        assertTrue(
            selector == accessControlId ? ok : ok == (selector == type(bytes4)(keccak256("supportsInterface(bytes4)")) ? ok : ok) && c.supportsInterface(accessControlId),
            "IAccessControl interface id must be supported"
        );
    }
}

