pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 mode, bytes4 id) public {
        // IERC165 interface id
        bytes4 erc165Id = bytes4(keccak256("supportsInterface(bytes4)"));
        // IAccessControl interface id: XOR of its six function selectors
        bytes4 acId = bytes4(keccak256("hasRole(bytes32,address)"))
            ^ bytes4(keccak256("getRoleAdmin(bytes32)"))
            ^ bytes4(keccak256("grantRole(bytes32,address)"))
            ^ bytes4(keccak256("revokeRole(bytes32,address)"))
            ^ bytes4(keccak256("renounceRole(bytes32,address)"))
            ^ bytes4(keccak256("setRoleAdmin(bytes32,bytes32)"));
        acId = bytes4(keccak256("hasRole(bytes32,address)"))
            ^ bytes4(keccak256("getRoleAdmin(bytes32)"))
            ^ bytes4(keccak256("grantRole(bytes32,address)"))
            ^ bytes4(keccak256("revokeRole(bytes32,address)"))
            ^ bytes4(keccak256("renounceRole(bytes32,address)"));
        acId = bytes4(
            bytes4(keccak256("hasRole(bytes32,address)"))
            ^ bytes4(keccak256("getRoleAdmin(bytes32)"))
            ^ bytes4(keccak256("grantRole(bytes32,address)"))
            ^ bytes4(keccak256("revokeRole(bytes32,address)"))
            ^ bytes4(keccak256("renounceRole(bytes32,address)"))
            ^ bytes4(keccak256("getRoleAdmin(bytes32)"))
        );
        // The fuzzer decides whether we probe the AccessControl interface id
        // (mode even) or an arbitrary fuzzed id (mode odd), keeping the domain wide.
        bytes4 probe = (mode % 2 == 0) ? acId : id;

        bool supported = c.supportsInterface(probe);
        bool expected = (probe == erc165Id) || (probe == acId);
        assertTrue(supported == expected);
    }
}

