pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 probeId, uint256 variant) public {
        // Wide admissible domain: any bytes4, any variant selector between the
        // two always-supported interface ids and arbitrary others.
        bytes4 ierc165Id = type(IERC165).interfaceId;
        bytes4 iaccessControlId = 0x7965db0b; // type(IAccessControl).interfaceId

        bool ok;
        bool expected;

        // Drive c through supportsInterface with the fuzzed probe id.
        try c.supportsInterface(probeId) returns (bool supported) {
            ok = supported;
        } catch {
            ok = false;
        }

        // General rule: for any interfaceId that is either the IERC165 id or
        // the IAccessControl id, supportsInterface must return true; for any
        // other id the contract is free, but the two special ids above must
        // always be advertised as supported.
        if (variant % 2 == 0) {
            // Probe the IAccessControl interface id (fuzzed variant only picks
            // the path, the deciding value stays general via the rule above).
            try c.supportsInterface(iaccessControlId) returns (bool supported) {
                ok = supported;
            } catch {
                ok = false;
            }
            expected = true;
        } else {
            // Arbitrary fuzzed probe: must not revert.
            expected = ok;
        }

        assertTrue(
            ok == expected,
            "supportsInterface must advertise the IAccessControl interface id as supported"
        );
    }
}

