pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes32 TIMELOCK_ADMIN_ROLE;
    bytes32 PROPOSER_ROLE;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
        TIMELOCK_ADMIN_ROLE = keccak256("TIMELOCK_ADMIN_ROLE");
        PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
    }

    function testFuzz_property(address actor, uint8 roleSelector) public {
        vm.assume(actor != address(0));
        bytes32 role = roleSelector % 2 == 0 ? TIMELOCK_ADMIN_ROLE : PROPOSER_ROLE;
        // Ground truth from construction: the deployer (this test contract) and c
        // hold TIMELOCK_ADMIN_ROLE; nobody else holds either role.
        bool expected =
            role == TIMELOCK_ADMIN_ROLE &&
            (actor == address(this) || actor == address(c));
        assertTrue(c.hasRole(role, actor) == expected);
    }
}

